                  <span
                    v-if="stage.review"
                    class="sl-status-pill sl-status-pill--sm"
                    :class="'sl-status-pill--' + statusKey(stage.review.status)"
                  >
                    {{ stage.review.statusDisplay }}
                  </span>
                  <span v-else-if="stage.isCurrent" class="slv-timeline-item__pending">
                    Awaiting review
                  </span>
                  <span v-else class="slv-timeline-item__pending slv-timeline-item__pending--muted">
                    Not yet reached
                  </span>
                </div>
                <template v-if="stage.review">
                  <div class="slv-timeline-item__meta">
                    {{ stage.review.reviewerName }} · {{ formatDate(stage.review.date) }}
                  </div>
                  <div class="slv-timeline-item__comments" v-if="stage.review.comments">
