<script>
import generalMixin from "../../mixins/general";

const PROFILE =
  "http://ihris.org/fhir/StructureDefinition/hod-recommended-transfer-profile";
const REVIEW_PROFILE =
  "http://ihris.org/fhir/StructureDefinition/review-hod-recommended-transfer-profile";

const REVIEWER_STAGES = [
  {
    code: "directorhr",
    label: "HR Director",
    status: "underhrdirectorreview",
    reviewPage: "hr-director-transfer-recommendation-review",
  },
  {
    code: "supervisor",
    label: "Supervisor",
    status: "undersupervisorreview",
    reviewPage: "supervisor-transfer-recommendation-review",
  },
  {
    code: "districthr",
    label: "District HR",
    status: "underdistricthrreview",
    reviewPage: "district-hr-transfer-recommendation-review",
  },
  {
    code: "districthod",
    label: "District HOD",
    status: "underdistricthodreview",
    reviewPage: "district-hod-transfer-recommendation-review",
  },
  {
    code: "ps",
    label: "PS",
    status: "underpsreview",
    reviewPage: "ps-transfer-recommendation-review",
  },
  {
    code: "hoddirector",
    label: "HOD Director — Applies Transfer",
    status: "psapproved",
    reviewPage: "hod-apply-transfer",
    // Not a peer review stage — there's no ReviewHODRecommendedTransfer
    // record for this step. It's the HOD Director physically applying the
    // transfer, derived straight from the transfer's own status rather
    // than from the `reviews` list.
    terminal: true,
  },
];

export default {
  name: "HodTransferRecommendationView",
  mixins: [generalMixin],
  props: ["queries"],

  data() {
    return {
      loading: true,
      error: null,

      accessChecked: false,
      isDirector: false,

      practitionerName: "",

      transfer: {
        plannedTransferDate: null,
        transferReason: "",
        status: null,
        statusDisplay: "Pending",
        eventDate: null,
      },

      currentPosition: {},
      destinationPosition: {},
      reviews: [],

      statusValueSetItems: [],
    };
  },

  computed: {
    backLabel() {
      return (this.queries && this.queries.returnLabel) || "Back";
    },

    initials() {
      if (!this.practitionerName) return "?";
      return this.practitionerName
        .split(" ")
        .filter(Boolean)
        .slice(0, 2)
        .map((n) => n[0].toUpperCase())
        .join("");
    },

    sectionMenu() {
      return [
        {
          name: "overview",
          title: "Overview",
          desc: "Reason, dates and status",
        },
        {
          name: "current-position",
          title: "Transfering From Position/Facility",
          desc: "Where the staff member is now",
        },
        {
          name: "destination-position",
          title: "Transfering To Position/Facility",
          desc: "Where the staff member is transferring to",
        },
        {
          name: "review-timeline",
          title: "Review Timeline",
          desc: "Status and comments from each reviewer",
        },
      ];
    },

    // True once the HOD Director has actually applied the transfer — i.e.
    // the transfer moved on from "psapproved" to some terminal status that
    // isn't a rejection/cancellation and isn't still "under...review".
    // Deliberately doesn't hardcode the eventual terminal status code (e.g.
    // "transferred"), since that's decided by the backend workflow.
    isTransferApplied() {
      const status = this.transfer.status || "";
      if (!status) return false;
      if (status === "psapproved") return false;
      if (status.includes("rejected") || status === "cancelled") return false;
      if (status.includes("review")) return false;
      return true;
    },

    timeline() {
      return REVIEWER_STAGES.map((stage) => {
        if (stage.terminal) {
          return {
            ...stage,
            review: this.isTransferApplied
              ? {
                  status: "approved",
                  statusDisplay: "Transfer Applied",
                  reviewerName: "HOD Director",
                  date: this.transfer.lastUpdated,
                  comments: "",
                }
              : null,
            isCurrent: this.currentStageCode === stage.code,
          };
        }
        return {
          ...stage,
          review: this.reviews.find((r) => r.reviewerCode === stage.code) || null,
          isCurrent: this.currentStageCode === stage.code,
        };
      });
    },

    currentStageCode() {
      return (
        REVIEWER_STAGES.find((s) => s.status === this.transfer.status)?.code || null
      );
    },

    currentStageLabel() {
      return REVIEWER_STAGES.find((s) => s.code === this.currentStageCode)?.label || null;
    },
  },

  async created() {
    await this.checkAccess();
    if (!this.isDirector) {
      this.loading = false;
      return;
    }

    if (!this.queries || !this.queries.id) {
      this.error = "No transfer recommendation specified.";
      this.loading = false;
      return;
    }

    await Promise.all([this.loadStatusValueSet(), this.loadRecommendation()]);
  },

  methods: {
    async checkAccess() {
      try {
        // Wait for generalMixin to finish loading loggedInStaff
        await new Promise((resolve) => {
          if (!this.loadingUserData) {
            resolve();
            return;
          }
          const unwatch = this.$watch("loadingUserData", (newValue) => {
            if (!newValue) {
              unwatch();
              resolve();
            }
          });
          setTimeout(() => {
            unwatch();
            resolve();
          }, 15000);
        });

        const practitionerId =
          this.loggedInStaff && this.loggedInStaff.practitioner;
        if (!practitionerId) {
          this.accessChecked = true;
          return;
        }

        const resp = await fetch(
          "/site/general/getDepartmentalDirector/" + practitionerId,
        );
        if (!resp.ok) throw new Error("HTTP " + resp.status);
        const directors = await resp.json();

        this.isDirector = Array.isArray(directors)
          ? directors.some((d) => d.practitioner === practitionerId)
          : false;
      } catch (err) {
        console.error("checkAccess error:", err);
        this.isDirector = false;
      } finally {
        this.accessChecked = true;
      }
    },

    async loadStatusValueSet() {
      try {
        const items = await this.$fhirutils.expand(
          "http://ihris.org/fhir/ValueSet/request-status-valueset",
        );
        this.statusValueSetItems = items || [];
      } catch (err) {
        console.error("loadStatusValueSet error:", err);
      }
    },

    // Extension urls come from the *Extension definition's* id, not the FSH
    // slice name — try the canonical id(s) first, fall back to the slice
    // name in case the upstream IG source is corrected later.
    getExt(resource, urlParts) {
      const candidates = Array.isArray(urlParts) ? urlParts : [urlParts];
      const exts = resource.extension || [];
      for (const part of candidates) {
        const found = exts.find((e) => e.url.includes(part));
        if (found) return found;
      }
      return null;
    },

    async loadRecommendation() {
      this.loading = true;
      this.error = null;

      try {
        const response = await fetch(`/fhir/Basic/${this.queries.id}`);
        if (!response.ok) {
          throw new Error("Transfer recommendation not found");
        }

        const resource = await response.json();
        if (!resource.meta?.profile?.includes(PROFILE)) {
          throw new Error("Resource is not a HOD recommended transfer");
        }

        const statusCoding = this.getExt(resource, ["request-status", "status"])
          ?.valueCoding;

        this.transfer = {
          plannedTransferDate: this.getExt(resource, "planned-transfer-date")
            ?.valueDate,
          transferReason: this.getExt(resource, ["reason", "transfer-reason"])
            ?.valueString,
          status: statusCoding?.code || null,
          statusDisplay: statusCoding?.display || "Pending",
          eventDate:
            this.getExt(resource, "event-date")?.valueDate ||
            resource.meta?.lastUpdated,
          // Unlike eventDate (which is the *original submission* date and
          // never changes), this reflects whenever the resource was last
          // modified — used as the "applied on" date for the HOD Director
          // stage, since nothing in the review/apply chain updates event-date.
          lastUpdated: resource.meta?.lastUpdated,
        };

        const practRef = this.getExt(resource, [
          "ihris-practitioner-reference",
          "practitioner",
        ])?.valueReference?.reference;

        // The backend workflow (createHODTransferRecommendationWorkflow.js)
        // writes these with the *correct* spelling — "destination-position" —
        // while the IG's FSH source has a typo ("destition-position"). Try
        // every variant so this keeps working regardless of which produced
        // the record being viewed.
        const curExt = this.getExt(resource, ["position-reference", "current-position"]);
        const destExt = this.getExt(resource, [
          "destination-position",
          "destition-position",
          "destination",
        ]);
        const curRef = curExt?.valueReference?.reference;
        const destRef = destExt?.valueReference?.reference;

        await Promise.all([
          this.loadPractitioner(practRef),
          this.loadPosition(curRef, "currentPosition", curExt?.valueReference?.display),
          this.loadPosition(destRef, "destinationPosition", destExt?.valueReference?.display),
          this.loadReviews(),
        ]);
      } catch (err) {
        console.error("Error loading transfer recommendation:", err);
        this.error = err.message || "Failed to load transfer recommendation details";
      } finally {
        this.loading = false;
      }
    },

    async loadReviews() {
      try {
        const res = await fetch(
          `/fhir/Basic?_profile=${REVIEW_PROFILE}&hodrecommendedtransfer=Basic/${this.queries.id}&_count=50`,
        );
        const bundle = await res.json();
        const resources = (bundle.entry || []).map((e) => e.resource);

        const reviewerRefs = [
          ...new Set(
            resources
              .map(
                (r) =>
                  this.getExt(r, ["ihris-practitioner-reference", "practitioner"])
                    ?.valueReference?.reference,
              )
              .filter(Boolean),
          ),
        ];
        const nameMap = {};
        await Promise.all(
          reviewerRefs.map(async (ref) => {
            try {
              const r = await fetch(`/fhir/${ref}?_elements=name`);
              const pract = await r.json();
              const name = pract.name?.[0];
              nameMap[ref] = name
                ? `${(name.given || []).join(" ")} ${name.family || ""}`.trim()
                : ref;
            } catch {
              nameMap[ref] = ref;
            }
          }),
        );

        this.reviews = resources.map((r) => {
          const reviewerRef = this.getExt(r, [
            "ihris-practitioner-reference",
            "practitioner",
          ])?.valueReference?.reference;
          const statusCoding = this.getExt(r, ["review-status", "status"])?.valueCoding;
          return {
            id: r.id,
            reviewerCode: this.getExt(r, "reviewer")?.valueCoding?.code,
            reviewerName: nameMap[reviewerRef] || "Unknown",
            status: statusCoding?.code || null,
            statusDisplay: statusCoding?.display || "Pending",
            comments: this.getExt(r, "comments")?.valueString || "",
            date: this.getExt(r, ["date", "event-date"])?.valueDate,
          };
        });
      } catch (error) {
        console.error("Error loading reviews:", error);
      }
    },

    async loadPractitioner(ref) {
      if (!ref) return;
      try {
        const id = ref.split("/")[1];
        const response = await fetch(`/fhir/Practitioner/${id}?_elements=name`);
        const practitioner = await response.json();
        const name = practitioner.name?.[0];
        this.practitionerName = name
          ? `${name.given?.join(" ") || ""} ${name.family || ""}`.trim()
          : "Unknown";
      } catch (error) {
        console.error("Error loading practitioner:", error);
        this.practitionerName = "Unknown";
      }
    },

    // Accepts refs either as "Basic/xxx" or a bare id.
    refId(ref) {
      if (!ref) return null;
      return ref.includes("/") ? ref.split("/")[1] : ref;
    },

    // Walk Location.partOf up the hierarchy (facility → council → district)
    // until a Location tagged with the district profile is found.
    async resolveDistrict(facilityRef) {
      try {
        let ref = facilityRef;
        for (let i = 0; i < 5 && ref; i++) {
          const id = this.refId(ref);
          if (!id) return "";
          const res = await fetch(`/fhir/Location/${id}`);
          if (!res.ok) return "";
          const loc = await res.json();
          if (loc.meta?.profile?.some((p) => p.includes("ls-district"))) {
            return loc.name || "";
          }
          ref = loc.partOf?.reference;
        }
        return "";
      } catch (error) {
        console.error("Error resolving district:", error);
        return "";
      }
    },

    async loadPosition(ref, target, fallbackDisplay) {
      // Seed with whatever the reference's own display carries, so the UI
      // shows *something* even if the deeper Basic/Location lookups below
      // fail (missing/unreachable resource, stale reference, etc.).
      this[target] = { designation: fallbackDisplay || "", loadError: null };
      if (!ref) return;

      try {
        const id = this.refId(ref);
        if (!id) return;
        const response = await fetch(`/fhir/Basic/${id}`);
        if (!response.ok) {
          console.error(
            `loadPosition: GET /fhir/Basic/${id} (${ref}) → HTTP ${response.status}`,
          );
          this[target] = {
            ...this[target],
            loadError: `Could not load position ${ref} (HTTP ${response.status})`,
          };
          return;
        }
        const position = await response.json();
        if (!position.extension?.length) {
          console.error(
            `loadPosition: Basic/${id} (${ref}) has no extensions — is it actually a position-profile resource?`,
            position,
          );
          this[target] = {
            ...this[target],
            loadError: `${ref} has no position data on it`,
          };
          return;
        }
        const getExt = (part, type) => {
          const ext = position.extension?.find((e) => e.url.includes(part));
          return ext ? ext[type] : null;
        };

        let designation = fallbackDisplay || "";
        const designationRef = getExt("designation", "valueReference")?.reference;
        if (designationRef) {
          try {
            const dId = this.refId(designationRef);
            const dRes = await fetch(`/fhir/Basic/${dId}`);
            const dData = await dRes.json();
            designation =
              dData.extension?.find((e) => e.url.includes("ihris-basic-name"))
                ?.valueString || designation;
          } catch {
            // designation lookup best-effort
          }
        }

        let facility = "";
        let district = "";
        const facilityRef = getExt("facility", "valueReference")?.reference;
        if (facilityRef) {
          try {
            const fId = this.refId(facilityRef);
            const fRes = await fetch(`/fhir/Location/${fId}`);
            const fData = await fRes.json();
            facility = fData.name || "";
          } catch {
            // facility lookup best-effort
          }
          district = await this.resolveDistrict(facilityRef);
        }

        let grade = "";
        const gradeRef = getExt("salary-grade", "valueReference")?.reference;
        if (gradeRef) {
          try {
            const gId = this.refId(gradeRef);
            const gRes = await fetch(`/fhir/Basic/${gId}`);
            const gData = await gRes.json();
            grade =
              gData.extension?.find((e) => e.url.includes("ihris-basic-name"))
                ?.valueString || "";
          } catch {
            // grade lookup best-effort
          }
        }

        const maxPosts = getExt("maximum-practitioners", "valueInteger") || 0;
        let filled = 0;
        try {
          const countRes = await fetch(
            `/fhir/PractitionerRole?roleposition=Basic/${id}&active=true&_summary=count`,
          );
          const countData = await countRes.json();
          filled = countData.total || 0;
        } catch {
          // vacancy count best-effort
        }

        this[target] = {
          designation,
          department: getExt("department", "valueCoding")?.display || "",
          facility,
          district,
          grade,
          maxPosts,
          vacant: Math.max(0, maxPosts - filled),
        };
      } catch (error) {
        console.error("Error loading position:", error);
      }
    },

    statusKey(status) {
      if (!status) return "warn";
      if (status === "approved") return "done";
      if (status.includes("rejected")) return "error";
      if (status === "cancelled") return "none";
      if (status.includes("review")) return "active";
      return "warn";
    },

    formatDate(dateString) {
      if (!dateString) return "N/A";
      const date = new Date(dateString);
      if (isNaN(date.getTime())) return "N/A";
      const day = String(date.getDate()).padStart(2, "0");
      const month = String(date.getMonth() + 1).padStart(2, "0");
      return `${day}/${month}/${date.getFullYear()}`;
    },

    goBack() {
      if (this.queries && this.queries.returnPath) {
        this.$router.push({
          path: this.queries.returnPath,
          query: this.queries.returnQuery
            ? JSON.parse(this.queries.returnQuery)
            : undefined,
        });
      } else if (window.history.length > 1) {
        this.$router.go(-1);
      } else {
        this.$router.push("/");
      }
    },

    scrollTo(section) {
      const el = document.getElementById(`section-${section}`);
      if (el) el.scrollIntoView({ behavior: "smooth" });
    },

    // Convenience link only — the destination review page does its own
    // access check, so this doesn't need to (and can't cheaply, from a
    // list of many rows) verify the viewer is actually this stage's
    // authorized reviewer before showing the button.
    goToReview() {
      const stage = REVIEWER_STAGES.find((s) => s.code === this.currentStageCode);
      if (!stage) return;
      this.$router.push({
        path: `/custom/${stage.reviewPage}`,
        query: {
          path: "/lesotho/components/transfers",
          request: this.queries.id,
        },
      });
    },
  },
};
</script>

